"use client";
import Link from 'next/link';import{useState}from'react';import{useRouter}from'next/navigation';import{getSupabaseBrowser}from'../../../lib/supabase/browser';
export default function VendorRegister(){const r=useRouter(),s=getSupabaseBrowser(),[f,setF]=useState({name:'',email:'',password:'',phone:'',address:''}),[busy,setBusy]=useState(false),[msg,setMsg]=useState('');async function submit(e){e.preventDefault();setBusy(true);setMsg('');try{const{data,error}=await s.auth.signUp({email:f.email,password:f.password,options:{data:{account_type:'vendor',vendor_name:f.name,phone:f.phone,address:f.address}}});if(error)throw error;if(data.session)r.push('/vendor');else setMsg('Account created. Check your email to confirm your account, then sign in to continue vendor onboarding.')}catch(e){setMsg(e.message||'Registration failed.')}finally{setBusy(false)}}return <main className="page"><style>{css}</style><header><Link href="/" className="brand"><span>IF</span><b>Intelligent Food<small>PROCUREMENT SYSTEM</small></b></Link><Link href="/vendor/login">Already registered? Sign in →</Link></header><section><div className="copy"><label>VENDOR REGISTRATION</label><h1>Start selling through <em>intelligent procurement.</em></h1><p>Create your vendor account first. After authentication, complete your restaurant profile and submit it for administrator approval.</p><div className="steps"><b>01 <span>Create account</span></b><b>02 <span>Complete vendor profile</span></b><b>03 <span>Wait for approval</span></b></div></div><form onSubmit={submit}><h2>Create vendor account</h2><p>Use an email you control. Your password is handled by Supabase Auth.</p><input required placeholder="Restaurant / business name" value={f.name} onChange={e=>setF({...f,name:e.target.value})}/><input required type="email" placeholder="Business email" value={f.email} onChange={e=>setF({...f,email:e.target.value})}/><input required minLength={8} type="password" placeholder="Password (8+ characters)" value={f.password} onChange={e=>setF({...f,password:e.target.value})}/><input placeholder="Phone" value={f.phone} onChange={e=>setF({...f,phone:e.target.value})}/><input placeholder="Business address" value={f.address} onChange={e=>setF({...f,address:e.target.value})}/><button disabled={busy}>{busy?'Creating account…':'Create vendor account →'}</button>{msg&&<div className="msg">{msg}</div>}</form></section></main>}
const css=`body{margin:0;background:#f5f3ee;color:#181813;font-family:Arial}.page{min-height:100vh}.page header{height:78px;background:#faf9f5;border-bottom:1px solid #dedbd2;display:flex;justify-content:space-between;align-items:center;padding:0 7vw}.brand{display:flex;align-items:center;gap:10px;text-decoration:none;color:#181813}.brand span{width:36px;height:36px;border-radius:50%;background:#314d3b;color:#fff;display:grid;place-items:center;font-weight:700}.brand b{font:700 16px Georgia}.brand small{display:block;font:700 7px Arial;letter-spacing:2px;color:#888;margin-top:3px}.page header>a:last-child{font-size:9px;color:#314d3b;text-decoration:none}.page section{max-width:1050px;margin:auto;padding:80px 6vw;display:grid;grid-template-columns:1.1fr .9fr;gap:80px;align-items:center}.copy label{font-size:8px;letter-spacing:2px;color:#b08b35;font-weight:700}.copy h1{font:700 54px Georgia;line-height:1.05;margin:15px 0}.copy h1 em{color:#314d3b}.copy>p{font-size:12px;color:#74736a;line-height:1.8}.steps{margin-top:35px;display:grid;gap:12px}.steps b{font-size:9px;color:#b08b35}.steps span{color:#181813;margin-left:12px;font-weight:400}form{background:#faf9f5;border:1px solid #dedbd2;padding:30px;display:grid;gap:10px}form h2{font:700 28px Georgia;margin:0}form p{font-size:9px;color:#777;line-height:1.6;margin:0 0 10px}form input{padding:13px;border:1px solid #dedbd2;background:#fff}form button{padding:14px;background:#314d3b;color:#fff;border:0;cursor:pointer;font-size:9px}form button:disabled{opacity:.6}.msg{font-size:9px;background:#ebe6d8;padding:12px;line-height:1.5}@media(max-width:800px){.page section{grid-template-columns:1fr;padding-top:50px}.copy h1{font-size:43px}}`;
